      } else if (0 <= typeCode && typeCode <= 3) {
        final var column =
            new MltMetadata.Column(
                null, new MltMetadata.ScalarField(MltMetadata.LogicalScalarType.ID));
        column.isNullable = (typeCode & 1) != 0;
        column.scalarType.hasLongId = (typeCode > 1);
        return column;
